const DB_KEY='shiguang-local-v1';
const isLocalDevice=window.__SHIGUANG_DEMO__||['127.0.0.1','localhost'].includes(location.hostname);
const seedDB={profile:{name:'林溪'},conversations:[],cards:[],evidence:[]};
const db=(()=>{try{return {...seedDB,...JSON.parse(localStorage.getItem(DB_KEY)||'{}')}}catch{return structuredClone(seedDB)}})();
db.collected ||= [];
db.settings ||= {background:'mist',partner:'拾光',ip:'温柔倾听者',dailyCardTime:'21:30'};
if(typeof db.settings.cloudPinned!=='boolean')db.settings.cloudPinned=false;
db.profile={name:'林溪',phone:'',birthday:'',city:'上海',bio:'喜欢植物、整理和记录生活。',interests:'植物照护、社区分享、手作',...db.profile};
const saveDB=()=>localStorage.setItem(DB_KEY,JSON.stringify(db));
const state={loggedIn:false,profileSetup:false,sidebarCollapsed:true,calendarYear:new Date().getFullYear(),calendarMonth:new Date().getMonth(),abilities:[],directions:[],people:[],monthlyReport:null,authView:'login',loginMethod:'password',passwordVisible:false,codeSent:false,loginNotice:'',talkMode:'conversation',ipPanelOpen:true,cloudEmotion:'neutral',friendPhoto:null,activeConversation:null,tab:'talk',subpage:null,skillModal:null,sidebar:false,moodSheet:false,listening:false,cameraSheet:false,cameraEnabled:false,report:false,mood:'平静',partnerMessages:{},messages:[
  {role:'ai',text:'我在这里。今天想从哪里开始说起？'}
]};

function ensureDemoDiscoveryData(){if(!isLocalDevice)return;if(!state.directions.length)state.directions=[{id:'demo-direction-1',title:'植物照护与生活记录',summary:'把日常观察整理成容易理解、可以持续使用的照护记录。'},{id:'demo-direction-2',title:'旧物改造与手作分享',summary:'从小型手作开始，和同好交换过程、材料与经验。'},{id:'demo-direction-3',title:'社区经验整理',summary:'把零散的生活经验整理成对邻里真正有帮助的小指南。'}];if(!state.people.length)state.people=[{id:'demo-person-1',name:'周禾',city:'上海',bio:'喜欢植物摄影和社区散步，正在整理一份四季植物观察册。',publicInterests:['植物观察','摄影记录','社区分享']},{id:'demo-person-2',name:'陈屿',city:'杭州',bio:'旧物改造爱好者，希望找到可以互相交换方法的小伙伴。',publicInterests:['旧物改造','手作','材料研究']},{id:'demo-person-3',name:'许清',city:'苏州',bio:'关注家庭照护与生活整理，擅长把复杂步骤写得简单清楚。',publicInterests:['生活整理','经验写作','照护']}]}

const reportItems=()=>{const source=db.cards.length?db.cards:(isLocalDevice?[{id:'demo-growth-card',conversationId:'demo-conversation',title:'我看见了自己的协调力',summary:'我在平衡不同需要的过程中，让事情往前走了一步。',createdAt:new Date(new Date().getFullYear(),new Date().getMonth(),3).getTime(),mood:'平静'}]:[]);const items=source.map(c=>({...c,date:new Date(c.createdAt).toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'}).replace('/','.'),tag:c.mood||'成长记录'}));if(items.length<2)return items;const today=new Date();const dailyIndex=(today.getFullYear()*372+(today.getMonth()+1)*31+today.getDate())%items.length;return [...items.slice(dailyIndex),...items.slice(0,dailyIndex)]};

const app=document.querySelector('#app');
function ensureReelArtwork(){document.querySelectorAll('.report-reel-first .reel-card').forEach(card=>{if(card.dataset.artReady)return;const image=document.createElement('img');image.src='./src/felt/daily-growth-card-v1.png';image.alt='今日随机展示的毛毡成长名片';image.className='daily-growth-card-art';card.prepend(image);card.dataset.artReady='true'})}
new MutationObserver(ensureReelArtwork).observe(app,{childList:true,subtree:true});
async function apiRequest(path,{method='GET',body:payload}={}){const token=localStorage.getItem('shiguang-token')||'';const response=await fetch(path,{method,headers:{...(payload!==undefined?{'content-type':'application/json'}:{}),...(token?{authorization:`Bearer ${token}`}:{})},...(payload!==undefined?{body:JSON.stringify(payload)}:{})});const data=await response.json().catch(()=>({message:'服务返回格式不正确。'}));if(!response.ok)throw new Error(data.message||'请求失败，请稍后重试。');return data}
const apiJSON=(path,payload)=>apiRequest(path,{method:'POST',body:payload});
async function hydrateAccount(){const month=new Date().toISOString().slice(0,7);let [{profile},conversationResult,cardResult,scheduleResult,signalResult,directionResult,peopleResult,reportResult]=await Promise.all([apiRequest('/api/v1/me'),apiRequest('/api/v1/conversations'),apiRequest('/api/v1/cards'),apiRequest('/api/v1/settings/card-schedule'),apiRequest('/api/v1/profile/signals'),apiRequest('/api/v1/directions'),apiRequest('/api/v1/people/recommendations'),apiRequest(`/api/v1/reports/monthly?month=${month}`)]);if(!(signalResult.signals||[]).length&&(conversationResult.conversations||[]).length){try{const generated=await apiJSON('/api/v1/insights/refresh',{});signalResult={signals:generated.abilities||[]};directionResult={directions:generated.directions||[]};reportResult={report:generated.report||null}}catch(error){console.warn('真实能力数据暂未生成：',error.message)}}db.profile={...db.profile,...profile,interests:Array.isArray(profile.interests)?profile.interests.join('、'):profile.interests||''};db.conversations=conversationResult.conversations||[];db.cards=cardResult.cards||[];db.settings.dailyCardTime=scheduleResult.schedule?.localTime||'21:30';state.abilities=signalResult.signals||[];state.directions=directionResult.directions||[];state.people=peopleResult.people||[];state.monthlyReport=reportResult.report||null;saveDB();return profile}
const abilityItems=()=>state.abilities;
document.addEventListener('click',event=>{const button=event.target.closest('[data-action="quick-card"]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();if(state.quickCardSaved)return;const latest=[...state.messages].reverse().find(message=>message.role==='user'&&message.text)?.text||'今天的一段重要对话';db.cards.unshift({id:`quick-card-${Date.now()}`,conversationId:state.activeConversation,title:latest.slice(0,18),createdAt:Date.now(),mood:state.mood,summary:'从当前对话中收入的成长片段。'});state.quickCardSaved=true;saveDB();render();setTimeout(()=>{state.quickCardSaved=false;render()},1100)},true);
document.addEventListener('click',event=>{const method=event.target.closest('[data-login-method]');if(!method)return;state.loginMethod=method.dataset.loginMethod;state.loginNotice='';render()});
document.addEventListener('click',async event=>{if(!event.target.closest('[data-device-login]'))return;event.preventDefault();event.stopImmediatePropagation();localStorage.setItem('shiguang-device-login','active');localStorage.setItem('shiguang-token','demo-session');db.profile.phone='13800138000';saveDB();try{await hydrateAccount()}catch(error){console.warn('演示数据加载失败：',error.message)}state.loggedIn=true;state.profileSetup=false;render()},true);
document.addEventListener('click',async event=>{const send=event.target.closest('[data-login-control="send-code"]');const submit=event.target.closest('[data-action="login"]');if(!send&&!submit)return;event.preventDefault();event.stopImmediatePropagation();const phone=document.querySelector('.login-form input[type="tel"]')?.value.trim()||'';const password=document.querySelector('.password-field input')?.value||'';const code=document.querySelector('.verify-field input')?.value.trim()||'';try{if(send){const result=await apiJSON('/api/v1/auth/code/request',{phone});state.codeSent=true;state.loginNotice=`${result.message}${result.devCode?` 验证码：${result.devCode}`:''}`;render();return}const path=state.authView==='register'?'/api/v1/auth/register':state.loginMethod==='code'?'/api/v1/auth/login/code':'/api/v1/auth/login/password';const result=await apiJSON(path,{phone,password,code});localStorage.setItem('shiguang-token',result.token);db.profile.phone=phone;const profile=await hydrateAccount();state.loggedIn=true;state.profileSetup=state.authView==='register'||!profile.onboardingComplete;state.loginNotice='';render()}catch(error){state.loginNotice=error.message||'暂时无法登录。';render()}},true);
async function submitChatInput(input){const text=input?.value.trim();if(!text)return;input.value='';input.blur();try{if(!state.activeConversation){const {conversation}=await apiJSON('/api/v1/conversations',{mood:state.mood});state.activeConversation=conversation.id;db.conversations.unshift(conversation)}state.messages.push({role:'user',text},{role:'ai',text:''});render();const response=await fetch(`/api/v1/conversations/${state.activeConversation}/messages`,{method:'POST',headers:{'content-type':'application/json',authorization:`Bearer ${localStorage.getItem('shiguang-token')||''}`},body:JSON.stringify({content:text,mode:'normal'})});if(!response.ok){const data=await response.json().catch(()=>null);throw new Error(data?.message||'暂时无法连接时光。')}const reader=response.body?.getReader();if(!reader)throw new Error('没有收到模型回复。');const decoder=new TextDecoder();while(true){const {value,done}=await reader.read();if(done)break;state.messages[state.messages.length-1].text+=decoder.decode(value,{stream:true});render()}const current=db.conversations.find(x=>x.id===state.activeConversation);if(current&&current.title==='尚未命名的新对话')current.title=text.slice(0,24);saveDB()}catch(error){if(state.messages.at(-1)?.role==='ai')state.messages[state.messages.length-1].text=`暂时没有连接成功：${error.message}`;render()}}
document.addEventListener('keydown',event=>{const input=event.target.closest('.composer textarea');if(!input||event.key!=='Enter'||event.shiftKey||!input.value.trim())return;event.preventDefault();event.stopImmediatePropagation();submitChatInput(input)},true);
document.addEventListener('click',event=>{const button=event.target.closest('[data-chat-send]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();submitChatInput(document.querySelector('.composer textarea'))},true);
document.addEventListener('click',event=>{if(event.target.closest('[data-open],[data-action="back"],[data-tab]'))requestAnimationFrame(()=>window.scrollTo({top:0,left:0,behavior:'instant'}))});
document.addEventListener('click',event=>{if(!event.target.closest('[data-action="back"]'))return;event.preventDefault();event.stopImmediatePropagation();state.subpage=state.subpage?.startsWith('real-partner-')?'partners':state.subpage==='partners'?'opportunity':null;render()},true);
document.addEventListener('click',event=>{const card=event.target.closest('.friend-section-one .social-profile-card');if(!card)return;event.preventDefault();event.stopImmediatePropagation();state.subpage=event.target.closest('[data-open]')?.dataset.open||'profile-card';state.sidebarCollapsed=true;render()},true);
document.addEventListener('click',event=>{const toy=event.target.closest('[data-cloud-toy]');if(toy){const moods=['happy','sad','cute'];state.cloudEmotion=moods[(moods.indexOf(state.cloudEmotion)+1)%moods.length];render();return}const emotion=event.target.closest('[data-cloud-emotion]');if(emotion){state.cloudEmotion=emotion.dataset.cloudEmotion;render();return}const control=event.target.closest('[data-cloud-action]');if(!control)return;state.ipPanelOpen=control.dataset.cloudAction==='open'||db.settings.cloudPinned;render()});
document.addEventListener('dblclick',event=>{if(!event.target.closest('.conversation-workspace')||event.target.closest('button,input,textarea'))return;state.ipPanelOpen=true;render()});
document.addEventListener('contextmenu',event=>{if(!event.target.closest('.cloud-ip-stage'))return;event.preventDefault();db.settings.cloudPinned=!db.settings.cloudPinned;state.ipPanelOpen=db.settings.cloudPinned||state.ipPanelOpen;saveDB();render()});
document.addEventListener('click',event=>{const view=event.target.closest('[data-auth-view]');if(view){state.authView=view.dataset.authView;state.loginNotice='';render();return}const action=event.target.closest('[data-login-control]');if(!action)return;if(action.dataset.loginControl==='password'){state.passwordVisible=!state.passwordVisible}else if(action.dataset.loginControl==='forgot'){state.loginNotice='验证码将发送到你的手机，用于重置密码。'}else if(action.dataset.loginControl==='send-code'){state.codeSent=true;state.loginNotice='验证码已发送，请注意查收。'}else if(action.dataset.loginControl==='qq'){state.loginNotice='正在连接 QQ 安全登录…'}else if(action.dataset.loginControl==='wechat'){state.loginNotice='正在连接微信安全登录…'}render()});
document.addEventListener('click',async event=>{if(!event.target.closest('[data-profile-save]'))return;const form=document.querySelector('.profile-settings-form');if(!form)return;const values=new FormData(form);try{const {profile}=await apiRequest('/api/v1/me',{method:'PATCH',body:{name:String(values.get('name')||''),birthday:String(values.get('birthday')||''),city:String(values.get('city')||''),bio:String(values.get('bio')||''),interests:String(values.get('interests')||'')}});db.profile={...db.profile,...profile,interests:(profile.interests||[]).join('、')};saveDB();state.subpage=null;state.tab='me';render()}catch(error){alert(error.message)}});
document.addEventListener('click',async event=>{if(!event.target.closest('[data-onboarding-save]'))return;const form=document.querySelector('.onboarding-form');if(!form)return;const values=new FormData(form);try{const {profile}=await apiJSON('/api/v1/me/onboarding',{name:String(values.get('name')||''),birthday:String(values.get('birthday')||''),city:String(values.get('city')||''),bio:String(values.get('bio')||'')});db.profile={...db.profile,...profile};saveDB();state.profileSetup=false;render()}catch(error){alert(error.message)}});
document.addEventListener('click',event=>{if(!event.target.closest('[data-action="login"]')||!state.loggedIn)return;state.profileSetup=true;render()});
document.addEventListener('click',event=>{if(!event.target.closest('[data-sidebar-collapse]'))return;state.sidebarCollapsed=!state.sidebarCollapsed;render()});
document.addEventListener('click',event=>{const button=event.target.closest('[data-calendar-step]');if(!button)return;const next=new Date(state.calendarYear,state.calendarMonth+Number(button.dataset.calendarStep),1);state.calendarYear=next.getFullYear();state.calendarMonth=next.getMonth();render()});
document.addEventListener('click',event=>{if(!event.target.closest('[data-action="toggle-navigation"]'))return;event.preventDefault();event.stopImmediatePropagation();state.sidebarCollapsed=!state.sidebarCollapsed;render()},true);
document.addEventListener('click',event=>{const tab=event.target.closest('[data-tab]');if(!tab)return;event.preventDefault();event.stopImmediatePropagation();state.tab=tab.dataset.tab;state.subpage=null;state.sidebar=false;state.sidebarCollapsed=true;if(state.tab==='talk')state.ipPanelOpen=true;render();requestAnimationFrame(()=>{const main=document.querySelector('.workspace-main');if(main)main.scrollTo({top:0,left:0,behavior:'instant'});window.scrollTo({top:0,left:0,behavior:'instant'})})},true);
document.addEventListener('click',event=>{const open=event.target.closest('[data-skill-modal]');const close=event.target.closest('.skill-modal-close')||event.target.matches('.skill-modal-layer');if(!open&&!close)return;event.preventDefault();event.stopImmediatePropagation();state.skillModal=open?Number(open.dataset.skillModal):null;render()},true);
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.skillModal!==null){state.skillModal=null;render()}});
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action="new-chat"]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();try{const {conversation}=await apiJSON('/api/v1/conversations',{mood:state.mood});db.conversations.unshift(conversation);state.sidebar=false;state.activeConversation=conversation.id;state.messages=[{role:'ai',text:'新的对话已经准备好了。今天你想先说哪一件事？'}];state.tab='talk';render()}catch(error){alert(error.message)}},true);
document.addEventListener('click',async event=>{const button=event.target.closest('[data-chat]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();try{const {conversation,messages}=await apiRequest(`/api/v1/conversations/${button.dataset.chat}`);state.sidebar=false;state.activeConversation=conversation.id;state.messages=messages.length?messages.map(m=>({role:m.role==='assistant'?'ai':'user',text:m.content})):[{role:'ai',text:'这段对话还没有内容。你想从哪里继续？'}];state.mood=conversation.mood||'平静';state.tab='talk';render()}catch(error){alert(error.message)}},true);
document.addEventListener('change',event=>{const setting=event.target.closest('[data-setting="dailyCardTime"]');if(!setting)return;db.settings.dailyCardTime=setting.value;saveDB();apiRequest('/api/v1/settings/card-schedule',{method:'PUT',body:{enabled:true,localTime:setting.value,timezone:'Asia/Shanghai'}}).catch(error=>alert(error.message))},true);
let cloudPullStart=null;
document.addEventListener('pointerdown',event=>{if(event.target.closest('.cloud-pull-handle'))cloudPullStart=event.clientY});
document.addEventListener('pointerup',event=>{if(cloudPullStart!==null&&event.clientY-cloudPullStart>18){state.ipPanelOpen=true;render()}cloudPullStart=null});
function render(){ensureDemoDiscoveryData();if(!state.loggedIn){app.innerHTML=loginPage();bind();return}if(state.profileSetup){app.innerHTML=onboardingPage();bind();return}ensureDailyCard();const content=state.subpage?detailPage(state.subpage):`<section class="page ${state.tab==='talk'?'active':''}" id="talk">${talkPage()}</section><section class="page ${state.tab==='friend'?'active':''}" id="friend">${friendPage()}</section><section class="page ${state.tab==='report'?'active':''}" id="report">${reportPage()}</section><section class="page ${state.tab==='me'?'active':''}" id="me">${mePage()}</section>`;app.innerHTML=`<main class="phone-shell workspace-shell ${state.sidebarCollapsed?'sidebar-collapsed':''} ${state.subpage?'has-subpage':''} tab-${state.tab} mood-theme-${state.mood}">
  ${workspaceSidebar()}${state.sidebarCollapsed?'':'<button class="sidebar-backdrop" data-action="toggle-navigation" aria-label="关闭主菜单"></button>'}<div class="workspace-main">
  <header class="app-head"><button class="menu-trigger" data-action="${state.subpage?'back':'toggle-navigation'}" aria-label="${state.subpage?'返回上一页':'展开主菜单'}">${state.subpage?'<i>←</i><span>返回</span>':'☰'}</button><button class="brand brand-menu" data-action="${state.subpage?'back':'toggle-navigation'}" aria-label="${state.subpage?'返回个人空间':'打开我是谁菜单'}"><i>我</i><div><b>${state.subpage?'个人空间':'我是谁'}</b><span>${state.subpage?'PRIVATE WORKSPACE':'BLUE ARCHIVE · PERSONAL FIELD'}</span></div></button><button class="privacy" data-action="open-privacy">隐私中心</button></header>
  ${content}
  </div>${state.sidebar?sidebar():''}${state.moodSheet?moodSheet():''}${state.cameraSheet?cameraSheet():''}${state.report?reportSheet():''}${state.skillModal!==null?skillModal(state.skillModal):''}
 </main>`;bind()}

function loginPage(){const register=state.authView==='register';const codeMode=!register&&state.loginMethod==='code';return `<main class="login-screen formal-login"><div class="login-tide" aria-hidden="true"><i></i><i></i><i></i></div><section><div class="login-brand-row"><div class="login-mark">拾</div><div><b>拾光</b><span>PRIVATE GROWTH ARCHIVE</span></div></div><header><span>${register?'创建账户':'欢迎回来'}</span><h1>${register?'注册你的拾光账户':'登录你的个人成长空间'}</h1><p>${register?'创建账号并设置密码，开始保存属于你的故事。':'继续记录故事、整理能力线索，并与同路人保持联系。'}</p></header>${register?'':`<div class="login-method-tabs"><button class="${state.loginMethod==='password'?'on':''}" data-login-method="password">账号密码</button><button class="${state.loginMethod==='code'?'on':''}" data-login-method="code">账号验证码</button></div>`}<div class="login-form"><label><span>手机号账号</span><input type="tel" placeholder="请输入手机号账号" autocomplete="tel" /></label>${register||codeMode?`<label class="verify-field"><span>账号验证码</span><input type="text" inputmode="numeric" maxlength="6" placeholder="请输入 6 位验证码"/><button type="button" data-login-control="send-code">${state.codeSent?'重新生成':'获取验证码'}</button></label>`:''}${register||!codeMode?`<label class="password-field"><span>${register?'设置密码':'账号密码'}</span><input type="${state.passwordVisible?'text':'password'}" placeholder="${register?'设置 8 位以上密码':'请输入账号密码'}" autocomplete="${register?'new-password':'current-password'}"/><button type="button" data-login-control="password">${state.passwordVisible?'隐藏':'显示'}</button></label>`:''}${register?'':`<div class="login-options"><label><input type="checkbox" checked/><span>记住登录</span></label>${codeMode?'<span>验证码仅显示在当前页面</span>':'<button data-login-control="forgot">忘记密码？</button>'}</div>`}${state.loginNotice?`<p class="login-notice">${state.loginNotice}</p>`:''}<button class="login-submit" data-action="login"><span>${register?'注册并进入拾光':'登录并进入拾光'}</span><b>↗</b></button>${!register&&isLocalDevice?'<button class="device-login" data-device-login><span>本设备一键登录</span><b>→</b></button>':''}<div class="register-row"><span>${register?'已经有账户？':'还没有账户？'}</span><button data-auth-view="${register?'login':'register'}">${register?'返回登录':'创建新账户'}</button></div></div><small class="login-legal">初版验证码由页面生成，不发送短信。你的对话、照片和成长记录默认仅自己可见。</small></section></main>`}
function onboardingPage(){return `<main class="onboarding-screen"><section><div class="onboarding-progress"><i></i><span>完成个人信息 · 1 / 1</span></div><header><div class="login-mark">拾</div><span>WELCOME TO SHIGUANG</span><h1>先让我们认识你。</h1><p>这些信息用于生成更贴近你的成长记录，也可以之后在“个人信息”中修改。</p></header><form class="onboarding-form"><div class="onboarding-grid"><label><span>你的名字</span><input name="name" value="${db.profile.name}" placeholder="怎么称呼你？"/></label><label><span>生日</span><input name="birthday" type="date" value="${db.profile.birthday}"/></label><label><span>所在城市</span><input name="city" value="${db.profile.city}" placeholder="例如：上海"/></label><label class="wide"><span>简单介绍一下自己</span><textarea name="bio" rows="4" placeholder="你喜欢什么？最近在关注什么？">${db.profile.bio}</textarea></label></div><button type="button" data-onboarding-save><span>保存并开始照见自己</span><b>↗</b></button></form><small>你的生日和个人资料默认仅自己可见。</small></section></main>`}
function cloudDeliveryAsset(){return {happy:"./src/assets/cloud_ip/animations/cloud_p5_happy.webp",sad:"./src/assets/cloud_ip/animations/cloud_p1_listen_empathy.webp",cute:"./src/assets/cloud_ip/animations/cloud_p4_touched.webp"}[state.cloudEmotion]||"./src/assets/cloud_ip/animations/cloud_p0_neutral.webp"}
function talkPage(){return `<div class="conversation-workspace ${state.ipPanelOpen?'ip-open':'ip-folded'} cloud-${state.cloudEmotion} ${db.settings.cloudPinned?'cloud-pinned':''}"><button class="cloud-pull-handle" data-cloud-action="open" aria-label="唤起云朵"><i>⌄</i></button><section class="talk-flow"><div class="ocean-motion" aria-hidden="true"><i></i><i></i><i></i><span></span></div><section class="cloud-ip-stage"><div class="cloud-scene" data-cloud-toy role="button" tabindex="0" aria-label="云朵玩偶，单击切换动作，右键设置常驻"><img class="cloud-delivery-art" src="${cloudDeliveryAsset()}" alt="陪伴对话的云朵" onerror="this.src='./src/assets/cloud_ip/static/cloud_neutral.png'"/><i class="cloud cloud-one"><span class="cloud-face"><b></b><b></b><em></em></span><span class="cloud-arm arm-left"></span><span class="cloud-arm arm-right"></span><span class="cloud-stitch"></span></i><i class="cloud-shadow"></i><span class="cloud-spark s1">✦</span><span class="cloud-spark s2">·</span></div></section><section class="conversation">${state.messages.map((m,i)=>`<article class="bubble ${m.role}">${m.role==='ai'?'<span>时光</span>':''}<p>${m.text||'<span class="thinking"><i></i><i></i><i></i></span>'}</p>${i===state.messages.length-1&&m.role==='ai'?'<small>你可以慢慢想，我在听。</small>':''}</article>`).join('')}</section>
 <section class="input-dock"><div class="signals"><button data-action="camera" class="${state.cameraEnabled?'on':''}"><i>⌾</i><span>表情辅助</span><small>${state.cameraEnabled?'已开启':'由你决定'}</small></button><button class="quick-card-button ${state.quickCardSaved?'saved':''}" data-action="quick-card"><i>▣</i><span>${state.quickCardSaved?'已收入卡片':'收入卡片'}</span><small>保存此刻</small></button><div><b>情绪信号</b><span>${state.mood} · 低强度</span></div></div><div class="composer"><button class="plus">＋</button><textarea placeholder="输入你的想法…" rows="1"></textarea><div class="composer-actions" role="group" aria-label="语音和发送"><button class="voice ${state.listening?'live':''}" data-action="voice"><span class="wave"><i></i><i></i><i></i><i></i></span><b>${state.listening?'停止':'说话'}</b></button><button class="chat-send" data-chat-send aria-label="发送消息"><b>↑</b></button></div></div><p>${state.listening?'正在聆听，说完后轻触停止':'按一下开始，再按一下结束'}</p></section></section></div>`}
function talkLanding(){return `<section class="talk-landing dot-matrix-landing"><div class="landing-index"><span>FIELD NOTE · 027</span><span>SHANGHAI / 31.23°N</span></div><div class="dot-stage" aria-hidden="true"><canvas id="dot-hero"></canvas><div class="dot-axis"><i></i><span>LISTENING FIELD</span><b>01</b></div></div><div class="landing-copy"><small>A QUIET PLACE FOR YOUR THOUGHTS</small><h1>今天，想从哪里<br/>开始说起？</h1><p>从一个画面、一点情绪，或者今天刚刚发生的小事开始。</p></div><div class="landing-actions"><button data-action="start-talk"><span>开始今天的对话</span><b>↗</b></button><button class="landing-mood" data-action="mood"><i>${moodIcon(state.mood)}</i><span>今日状态</span><b>${state.mood}</b></button></div></section>`}

function reportPage(){const all=reportItems();const past=all.slice(0,1);const saved={};all.forEach((card,index)=>{const date=new Date(card.createdAt);if(date.getFullYear()===state.calendarYear&&date.getMonth()===state.calendarMonth)saved[date.getDate()]={...card,index}});const firstDay=new Date(state.calendarYear,state.calendarMonth,1).getDay();const dayCount=new Date(state.calendarYear,state.calendarMonth+1,0).getDate();const blanks=Array.from({length:firstDay},()=>'<i class="calendar-empty"></i>').join('');const days=Array.from({length:dayCount},(_,i)=>{const day=i+1;const card=saved[day];return card?`<button class="calendar-day has-card card-tone-${day%3}" data-open="card-${card.index}"><time>${day}</time><span>${card.tag}</span><b>${card.title}</b></button>`:`<div class="calendar-day"><time>${day}</time></div>`}).join('');const review=past.length?`<div class="reel-window"><div class="reel-track">${past.map((r,i)=>`<article data-open="card-${i}" class="reel-card reel-${i%3}"><div><time>${r.date}</time><small>${r.tag}</small><h3>${r.title}</h3><span>打开回顾 ↗</span></div></article>`).join('')}</div></div>`:`<div class="real-data-empty"><h3>还没有成长卡片</h3><p>卡片会根据真实对话生成并保存到云端，这里不再显示演示内容。</p></div>`;return `<section class="daily-reel report-reel-first"><header><div><span>PAST CONVERSATION CARDS</span><h2>往日名片回顾</h2></div></header>${review}</section><section class="growth-calendar"><header><div><span>GROWTH CALENDAR</span><h2>${state.calendarYear} 年 ${state.calendarMonth+1} 月</h2></div><div class="calendar-nav"><button data-calendar-step="-1" aria-label="上个月">‹</button><b>成长月历</b><button data-calendar-step="1" aria-label="下个月">›</button></div></header><div class="calendar-weekdays">${['日','一','二','三','四','五','六'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${blanks}${days}</div><footer class="calendar-footer"><span>${Object.keys(saved).length?`${Object.keys(saved).length} 张成长卡片`:'这个月还没有成长卡片'}</span><button class="monthly-summary-button" data-open="full-report"><i>✦</i> 月度总结 <b>↗</b></button></footer></section>`}

function friendPage(){const interests=String(db.profile.interests||'').split(/[、,，]/).filter(Boolean);const skills=abilityItems().slice(0,4).map(x=>x.label);const directionSummary=state.directions.map(x=>x.title).join(' · ');return `<section class="friend-opportunity-wrap friend-section-one"><article class="social-profile-card plain-social-card" data-open="opportunity" role="button" tabindex="0"><header><span>MY SOCIAL CARD · 01</span><b>${db.profile.city||'城市未设置'} · 可线上交流</b></header><div class="social-card-main"><div class="social-card-avatar">${db.profile.name.slice(0,1)}</div><div class="social-card-identity"><h2>${db.profile.name}</h2><p>${db.profile.bio||'暂未填写个人介绍。'}</p></div><i class="social-card-code" aria-hidden="true">我</i></div><div class="social-story-list social-story-two"><section><small>感兴趣</small><h3>${interests.join(' · ')||'暂未填写'}</h3><p>来自你保存的个人资料。</p></section><section><small>擅长</small><h3>${skills.join(' · ')||'尚未从真实对话中形成能力线索'}</h3><p>由 AI 根据真实对话证据整理。</p></section></div><footer><small>个人资料默认仅在你确认后展示</small><div><button class="social-card-primary" data-open="opportunity">查看探索方向 ↗</button><button data-open="profile-card">预览社交名片</button></div></footer></article></section><section class="friend-direction-teaser"><header><span>02 · EXPLORE DIRECTIONS</span><h2>选择一个方向，寻找同好</h2><p>${state.directions.length?'这些方向来自你的真实对话和能力证据。':'目前证据还不足，AI 暂未生成探索方向。'}</p></header><button data-open="opportunity"><span>${directionSummary||'暂无真实方向数据'}</span><b>打开探索方向 ↗</b></button></section>`}
function mePage(){const abilities=abilityItems();return `<section class="ability-cloudscape portrait-ability-card"><header><span>SKILL FIELD / ${abilities.length} SIGNALS</span><h2>已发现的能力线索</h2><p>每一条能力都来自你的真实对话。点击能力泡泡，查看对应的生活事件。</p></header>${abilities.length?`<div class="ability-sky"><div class="ability-main-cloud" aria-hidden="true"><img class="ability-cloud-delivery-art" src="./src/assets/cloud_ip/animations/cloud_p3_quiet_company.webp" alt="" onerror="this.src='./src/assets/cloud_ip/static/cloud_neutral.png'"/><i></i><i></i><span></span></div>${abilities.slice(0,10).map((s,i)=>`<button class="ability-bubble bubble-${i}" data-skill-modal="${i}" title="${s.evidence}"><b>${s.label}</b><span>${s.category}</span></button>`).join('')}<i class="ability-glint glint-a">✦</i><i class="ability-glint glint-b">·</i></div><footer><span>来自真实对话与云端记录</span><button data-open="vocabulary">查看全部能力词库 ↗</button></footer>`:`<div class="real-data-empty"><i>◇</i><h3>还没有形成能力线索</h3><p>继续在“照见自己”中讲述真实经历，AI 会基于你的原话整理，不会使用示例数据填充。</p></div>`}</section>
 <section class="settings"><button data-open="memory"><span>个人档案与记忆</span><b>23 条记录 ›</b></button></section>`}

function moodIcon(mood){return {轻松:'❀',平静:'❋',疲惫:'❦',焦虑:'✣',开心:'✿',低落:'☁'}[mood]||'❋'}
function moodSheet(){const moods=[['轻松','今天有一点余裕'],['平静','状态稳定，可以慢慢聊'],['疲惫','希望被温柔地陪伴'],['焦虑','脑子里有很多事情'],['开心','想分享一件好事'],['低落','不想解释太多']];return `<div class="overlay" data-action="close-mood"><section class="sheet mood-sheet" onclick="event.stopPropagation()"><button class="close" data-action="close-mood">×</button><span>CHECK IN · ONLY FOR THIS TALK</span><h2>今天的你，<br/>更接近哪种状态？</h2><div>${moods.map(x=>`<button data-mood="${x[0]}" class="mood-${x[0]} ${state.mood===x[0]?'selected':''}"><i>${moodIcon(x[0])}</i><b>${x[0]}</b><span>${x[1]}</span></button>`).join('')}</div><p>这不是诊断，只用于调整这次对话的节奏和语气。</p></section></div>`}
function profileSettingsPage(){return `<section class="detail-page active profile-settings-page"><header><span>PERSONAL INFORMATION</span><h1>设置个人信息</h1><p>这些信息用于完善你的个人画像和同路人匹配，不会自动公开。</p></header><form class="profile-settings-form"><div class="profile-avatar-editor"><i>${db.profile.name.slice(0,1)}</i><div><b>${db.profile.name}</b><label>更换头像<input type="file" accept="image/*"/></label></div></div><div class="profile-form-grid"><label><span>昵称</span><input name="name" value="${db.profile.name}"/></label><label><span>生日</span><input name="birthday" type="date" value="${db.profile.birthday}"/></label><label><span>手机号码</span><input name="phone" type="tel" value="${db.profile.phone}" placeholder="用于账户安全"/></label><label><span>所在城市</span><input name="city" value="${db.profile.city}"/></label><label class="wide"><span>个人介绍</span><textarea name="bio" rows="4">${db.profile.bio}</textarea></label><label class="wide"><span>兴趣与关注方向</span><input name="interests" value="${db.profile.interests}"/><small>使用顿号分隔，例如：植物照护、社区活动、手作</small></label></div><button type="button" data-profile-save>保存个人信息</button></form></section>`}
function socialCardPage(){const interests=String(db.profile.interests||'植物照护、社区分享、手作').split(/[、,，]/).filter(Boolean);const skills=abilityItems().slice(0,3).map(x=>x.label);return `<section class="detail-page active social-card-preview-page felt-social-page"><header><span>SOCIAL CARD PREVIEW</span><h1>我的个人社交名片</h1><p>这是同路人看到的公开预览。手机号、生日和私人对话不会显示。</p></header><article class="social-profile-card social-profile-card-preview plain-social-card felt-social-card"><header><span>SHIGUANG MEMBER · 01</span><b>${db.profile.city||'上海'} · 可线上交流</b></header><div class="social-card-main"><div class="social-card-avatar">${db.profile.name.slice(0,1)||'林'}</div><div class="social-card-identity"><h2>${db.profile.name||'林溪'}</h2><p>${db.profile.bio||'喜欢植物、整理和记录生活，希望认识认真生活的同路人。'}</p></div><i class="social-card-code">拾</i></div><div class="social-story-list"><section><small>正在做</small><h3>植物照护与生活记录</h3><p>持续记录阳台植物的变化，并整理容易理解的照护方法。</p></section><section><small>感兴趣</small><h3>${interests.join(' · ')}</h3><p>希望和认真生活的人交换经验，一起做小而真实的内容项目。</p></section><section><small>擅长</small><h3>${skills.join(' · ')||'观察 · 整理 · 耐心照护'}</h3><p>善于发现细节，把零散经验变成可以重复使用的方法。</p></section></div><footer><small>拾光 · 个人成长档案</small><div><button type="button">保存图片</button><button class="social-card-primary" type="button">分享名片 ↗</button></div></footer></article></section>`}

function detailPage(type){const cards=reportItems();if(type==='full-report')return fullReportPage();if(type==='profile-settings')return profileSettingsPage();if(type==='profile-card')return socialCardPage();if(type.startsWith('card-'))return cardDetailPage(Number(type.split('-')[1]));if(type.startsWith('real-partner-chat-'))return partnerChatPage(Number(type.split('-').at(-1)));if(type.startsWith('real-partner-'))return realPartnerPage(Number(type.split('-').at(-1)));const data={
 opportunity:{eyebrow:'DIRECTION DISCOVERY · STEP 02',title:'选择一个方向，寻找同好',intro:'这些方向由 AI 根据真实对话与能力证据整理。',body:state.directions.length?`<section class="direction-discovery"><section class="explorable-directions compact-direction-list">${state.directions.map((x,i)=>`<button data-open="partners"><strong>${String(i+1).padStart(2,'0')}</strong><div><small>来自真实能力证据</small><h3>${x.title}</h3><p>${x.summary}</p></div><em>寻找同好 ↗</em></button>`).join('')}</section><footer class="direction-note"><span>说明</span><p>探索方向来自真实对话，不代表合作或收入保证。</p></footer></section>`:`<div class="real-data-empty"><h3>暂时没有可探索方向</h3><p>AI 尚未从真实对话中找到足够证据，因此不会显示示例方向。</p></div>`},
 partners:{eyebrow:'PARTNER DISCOVERY',title:'寻找伯牙',intro:'只展示真实注册并主动允许被发现的用户。',body:state.people.length?`<div class="partner-filters"><button class="on">真实用户</button><button>同城</button><button>可线上</button></div><div class="partner-list">${state.people.map((x,i)=>`<article><div class="partner-avatar">${x.name?.[0]||'人'}</div><div><small>${x.city||'城市未公开'}</small><h3>${x.name||'未命名用户'}</h3><p>${x.bio||'对方暂未填写公开介绍。'}</p><span>感兴趣：${(x.publicInterests||[]).join(' · ')||'暂未公开'}</span></div><div class="partner-card-actions"><button class="partner-profile-entry" data-open="real-partner-${i}"><span>查看公开资料</span><b>先了解她 ↗</b></button><button class="partner-chat-entry" data-open="real-partner-chat-${i}"><span>进入聊天</span><b>开始对话 ↗</b></button></div></article>`).join('')}</div>`:`<div class="real-data-empty"><h3>暂时还没有可以推荐的伯牙</h3><p>当前没有其他用户主动公开资料。这里不会使用虚构人物填充。</p></div>`},
 memory:{eyebrow:'MEMORY & PROFILE',title:'我的手账',intro:'重要的句子、日常图像和成长证据，被整理成一本可以慢慢翻阅的私人手账。',body:`<article class="journal-cover"><img src="./src/assets/botanical-journal.png" alt="阳台植物与手写观察纸张"/><div><small>AUGUST · FIELD NOTES</small><h2>照顾，也是一种创造。</h2><p>在重复的日常里，你正在建立自己的观察方式。</p></div></article><section class="selected-lines"><span>SELECTED LINES</span><blockquote>“我想让每一盆植物，都有一个容易被理解的位置。”</blockquote><blockquote>“整理不是把东西藏起来，而是知道下一次怎么继续。”</blockquote></section><div class="memory-list">${[['08.27','你会为植物建立容易维护的分类'],['08.24','你更喜欢先观察，再决定如何行动'],['08.19','你认为家庭劳动也应该被看见'],['08.12','你曾帮助邻居理解收纳步骤']].map((x,i)=>`<article data-open="card-${Math.min(i,Math.max(0,cards.length-1))}"><time>${x[0]}</time><p>${x[1]}</p><button data-open="card-${Math.min(i,Math.max(0,cards.length-1))}">翻阅</button></article>`).join('')}</div>`},
 vocabulary:{eyebrow:'ABILITY LEXICON',title:'全部能力词库',intro:'这里只展示能够回到真实对话和行动证据的能力线索。',body:abilityItems().length?`<div class="vocabulary-grid">${abilityItems().map((s,i)=>`<button data-skill-modal="${i}"><span>${String(i+1).padStart(2,'0')}</span><div><b>${s.label}</b><small>${s.category} · ${s.confidence}%</small></div><em>查看证据 ↗</em></button>`).join('')}</div>`:`<div class="real-data-empty"><h3>暂无真实能力数据</h3><p>完成更多对话后再回来看看。</p></div>`},
 privacy:{eyebrow:'DATA CONTROL',title:'数据与摄像头权限',intro:'语音、摄像头和长期记忆都必须由你主动决定。',body:`<div class="control-list"><article><div><b>语音输入</b><span>仅在按下说话后工作</span></div><button class="switch on"><i></i></button></article><article><div><b>表情辅助</b><span>${state.cameraEnabled?'本次对话已开启':'默认关闭，不保存原始视频'}</span></div><button class="switch ${state.cameraEnabled?'on':''}"><i></i></button></article><article><div><b>长期记忆</b><span>用于连接不同时间的对话</span></div><button class="switch on"><i></i></button></article><article><div><b>匿名改进</b><span>不使用你的内容训练公共模型</span></div><button class="switch"><i></i></button></article></div>`},
 export:{eyebrow:'PORTABLE ARCHIVE',title:'导出我的内容',intro:'你的对话、卡片和报告应该随时可以带走。',body:`<div class="export-options"><button><i>TXT</i><div><b>完整对话记录</b><span>按日期整理的可读文本</span></div><em>↓</em></button><button><i>PDF</i><div><b>成长卡片与报告</b><span>适合保存和打印</span></div><em>↓</em></button><button><i>JSON</i><div><b>结构化个人档案</b><span>包含记忆、能力与证据关系</span></div><em>↓</em></button></div><p class="export-note">导出只会在你的设备上生成文件，不会公开内容。</p>`}
 }[type];return `<section class="detail-page active"><header><span>${data.eyebrow}</span><h1>${data.title}</h1><p>${data.intro}</p></header>${data.body}</section>`}

function fullReportPage(){const r=state.monthlyReport;const month=r?.month||new Date().toISOString().slice(0,7);const [year,number]=month.split('-');return `<section class="detail-page report-detail active"><header><span>MONTHLY REVIEW · ${month}</span><h1>${Number(number)} 月月度总结</h1><p>根据云端保存的真实对话与成长卡片，由 AI 整理。</p></header>${r?`<article class="monthly-letter"><div class="monthly-letter-index"><span>${year}</span><b>${number}</b><small>MONTHLY LETTER</small></div><div class="monthly-letter-body"><small>写给这个月的你</small><h2>${r.title}</h2><p>${r.summary}</p><footer><span>本月关键词</span><strong>${(r.keywords||[]).join(' · ')||'尚未提取'}</strong></footer></div></article>`:`<div class="real-data-empty"><h3>这个月还没有总结</h3><p>真实对话积累到足够证据后，AI 才会生成月度总结。</p></div>`}</section>`}
