function skillDetailPage(index){const s=skillVocabulary[index]||skillVocabulary[0];const confidence=Math.round(s.confidence);const pages=[['01','AI 综合判断',`你倾向于先理解差异，再建立可以持续使用的方法。`,`这项能力反复出现在观察、分类、照护和向他人解释的过程中。你能够把零散信息转化为清楚、可执行的秩序。`],['02','典型表现','你通常怎样使用这项能力？','主动发现细微差异；建立标签、步骤或分类规则；关注方法能否长期维护；能解释自己的判断依据。'],['03','适用场景','这项能力可能在哪里继续生长？','内容与资料整理、新手指南和流程设计、社区照护与知识分享，以及需要耐心观察的协作项目。'],['04','边界与待验证','这仍是一条需要继续验证的线索。','目前证据主要来自日常生活场景，还不足以证明它在高压力、多人协作或商业项目中也会稳定发挥。']];const evidencePages=[reports[0],reports[1],reports[2],{date:'07.28',title:'为邻居说明植物养护步骤',tag:'经验表达',color:'#8fac9d'}];return `<section class="detail-page skill-detail active"><header><span>AI ABILITY DOCUMENT · UPDATED TODAY</span><h1>${s.label}能力观察说明书</h1><p>向右翻阅四张名片，查看综合判断、典型表现、适用场景和待验证边界。</p></header><section class="ability-book"><header><div><small>${s.category} · 能力线索 ${String(index+1).padStart(2,'0')}</small><b>${confidence}% 证据置信度</b></div><span>横向滑动翻页 →</span></header><div class="ability-book-pages">${pages.map((p,i)=>`<article class="ability-page-card page-${i}"><div class="page-number"><b>${p[0]}</b><span>/ 04</span></div><small>${p[1]}</small><h2>${p[2]}</h2><p>${p[3]}</p><footer><span>${s.label}</span><b>我是谁 · AI 观察</b></footer></article>`).join('')}</div><div class="book-dots">${pages.map((_,i)=>`<i class="${i===0?'on':''}"></i>`).join('')}</div></section><section class="evidence-journal evidence-book"><header><div><small>EVIDENCE BOOK</small><h2>证据索引</h2></div><span>向右翻阅 01—04 →</span></header><div class="evidence-pages">${evidencePages.map((r,i)=>`<button class="evidence-page evidence-tone-${i}" data-open="card-${Math.min(i,reports.length-1)}"><strong>${String(i+1).padStart(2,'0')}</strong><small>真实记录 · ${r.date}</small><h3>${r.title}</h3><p>${i===0?'直接支持这项能力判断，是目前关联度最高的行动记录。':'从不同生活场景补充这项能力的形成过程。'}</p><footer><span>${r.tag}</span><em>阅读原文 ↗</em></footer></button>`).join('')}</div><div class="book-dots"><i class="on"></i><i></i><i></i><i></i></div></section><section class="doc-actions"><button>这份整理准确</button><button>补充或修正</button></section></section>`}

