function bind(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;state.subpage=null;render()});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=e=>{e.stopPropagation();state.subpage=b.dataset.open;state.sidebar=false;render()});document.querySelectorAll('[data-chat]').forEach(b=>b.onclick=()=>{const c=db.conversations.find(x=>x.id===b.dataset.chat);state.sidebar=false;state.talkMode='conversation';state.activeConversation=b.dataset.chat;if(c){state.messages=c.messages;state.mood=c.mood||'平静'}render()});document.querySelectorAll('[data-mood]').forEach(b=>b.onclick=()=>{state.mood=b.dataset.mood;state.moodSheet=false;persistConversation();render()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=e=>{const a=b.dataset.action;if(a==='login'){localStorage.setItem('shiguang-session','active');state.loggedIn=true;render()}if(a==='back'){state.subpage=state.subpage?.startsWith('partner-')?'partners':null;render()}if(a==='open-privacy'){state.subpage='privacy';render()}if(a==='mood'){state.moodSheet=true;render()}if(a==='close-mood'){state.moodSheet=false;render()}if(a==='sidebar'){state.sidebar=true;render()}if(a==='close-sidebar'){state.sidebar=false;render()}if(a==='new-chat'){const id=`talk-${Date.now()}`;const c={id,title:'尚未命名的新对话',mood:state.mood,createdAt:Date.now(),messages:[{role:'ai',text:'新的对话已经准备好了。今天你想先说哪一件事？'}]};db.conversations.unshift(c);saveDB();state.sidebar=false;state.activeConversation=id;state.messages=c.messages;state.talkMode='conversation';state.tab='talk';render()}if(a==='start-talk'){state.talkMode='conversation';render()}if(a==='voice'){state.listening=!state.listening;persistConversation();render()}if(a==='camera'){state.cameraSheet=true;render()}if(a==='close-camera'){state.cameraSheet=false;render()}if(a==='allow-camera'){state.cameraSheet=false;state.cameraEnabled=true;state.mood='专注';persistConversation();render()}if(a==='make-report'){persistConversation();state.report=true;render()}if(a==='close-report'){state.report=false;render()}if(a==='save-card'){const card={id:`card-${Date.now()}`,conversationId:state.activeConversation,title:'一次有温度的整理',createdAt:Date.now(),mood:state.mood};db.cards.unshift(card);db.evidence.push({cardId:card.id,skills:['观察力','分类能力','持续照护']});saveDB();state.report=false;state.tab='report';state.talkMode='conversation';render()}});document.querySelectorAll('[data-setting]').forEach(el=>el.onchange=()=>{db.settings[el.dataset.setting]=el.value;saveDB();render()});const input=document.querySelector('.composer textarea');if(input)input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&input.value.trim()){e.preventDefault();const text=input.value.trim();state.messages.push({role:'user',text},{role:'ai',text:'我记下来了。你愿意再说说，这件事里哪一个决定最像你自己吗？'});const c=db.conversations.find(x=>x.id===state.activeConversation);if(c&&c.title==='尚未命名的新对话')c.title=text.slice(0,16);persistConversation();render()}};bindPartnerChat();bindCollectors()}
function bindPartnerChat(){document.querySelectorAll('[data-partner-send]').forEach(button=>{const send=()=>{const index=Number(button.dataset.partnerSend);const person=state.people[index];const input=document.querySelector(`[data-partner-input="${index}"]`);const text=input?.value.trim();if(!text||!person)return;state.partnerMessages[index]||=[{role:'partner',text:`你好，我是${person.name||'你的新朋友'}。很高兴在这里认识你，可以先聊聊我们共同感兴趣的方向。`}];state.partnerMessages[index].push({role:'me',text},{role:'partner',text:'收到，很高兴认识你。这个方向和我的经验很互补，我们可以先把目标和第一次小尝试聊清楚。'});render()};button.onclick=send;const input=document.querySelector(`[data-partner-input="${button.dataset.partnerSend}"]`);if(input)input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}}})}
function bindCollectors(){let dragged='';document.querySelectorAll('[data-skill-drag]').forEach(el=>{el.ondragstart=e=>{dragged=el.dataset.skillDrag;e.dataTransfer.setData('text/plain',dragged);el.classList.add('dragging')};el.ondragend=()=>el.classList.remove('dragging')});const box=document.querySelector('[data-dropbox]');if(box){box.ondragover=e=>{e.preventDefault();box.classList.add('ready')};box.ondragleave=()=>box.classList.remove('ready');box.ondrop=e=>{e.preventDefault();const word=e.dataTransfer.getData('text/plain')||dragged;if(word&&!db.collected.includes(word)){db.collected.push(word);saveDB()}render()}}const file=document.querySelector('[data-action="add-photo"]');if(file)file.onchange=()=>{if(file.files?.[0]){db.cards.unshift({id:`photo-${Date.now()}`,title:'今天添加的一张照片',createdAt:Date.now(),mood:state.mood});saveDB();render()}};document.querySelectorAll('[data-action="add-friend-photo"]').forEach(input=>input.onchange=()=>{const image=input.files?.[0];if(!image)return;const reader=new FileReader();reader.onload=()=>{state.friendPhoto=reader.result;render()};reader.readAsDataURL(image)});initDotHero()}

function initDotHero(){
 const canvas=document.querySelector('#dot-hero');if(!canvas)return;
 const ctx=canvas.getContext('2d');const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 let w=0,h=0,dpr=1,points=[],pointer={x:-999,y:-999,active:false};
 const resize=()=>{const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);w=r.width;h=r.height;canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);points=[];
  const gap=w<390?8:9,cx=w*.57,cy=h*.47,maxR=Math.min(w,h)*.43;
  for(let y=7;y<h;y+=gap)for(let x=7;x<w;x+=gap){const dx=x-cx,dy=y-cy;const r=Math.hypot(dx,dy),a=Math.atan2(dy,dx);const edge=maxR*(.66+.15*Math.cos(a*5)+.055*Math.cos(a*10));const field=Math.sin(x*.045)+Math.cos(y*.038);if(r<edge+field*5||Math.random()<.025*Math.max(0,1-r/maxR))points.push({x,y,seed:Math.random()*6.28,size:.65+Math.random()*1.45,depth:Math.max(0,1-r/maxR)});}
 };
 const locate=e=>{const r=canvas.getBoundingClientRect(),p=e.touches?.[0]||e;pointer.x=p.clientX-r.left;pointer.y=p.clientY-r.top;pointer.active=true};
 canvas.addEventListener('pointermove',locate);canvas.addEventListener('pointerleave',()=>pointer.active=false);canvas.addEventListener('touchmove',locate,{passive:true});
 resize();new ResizeObserver(resize).observe(canvas);
 const draw=now=>{if(!canvas.isConnected)return;ctx.clearRect(0,0,w,h);const t=now*.001;
  for(const p of points){let x=p.x+Math.sin(t*.7+p.y*.035+p.seed)*2.4,y=p.y+Math.cos(t*.55+p.x*.028+p.seed)*2;let force=0;if(pointer.active){const dx=x-pointer.x,dy=y-pointer.y,dist=Math.hypot(dx,dy);if(dist<92){force=(92-dist)/92;x+=dx/(dist||1)*force*18;y+=dy/(dist||1)*force*18;}}
   const pulse=.78+.22*Math.sin(t*1.1+p.seed);ctx.beginPath();ctx.arc(x,y,p.size*(.72+p.depth*.55+force*.32)*pulse,0,Math.PI*2);ctx.fillStyle=`rgba(29,76,151,${.24+p.depth*.66})`;ctx.fill();
  }
  if(!reduced)requestAnimationFrame(draw);
 };requestAnimationFrame(draw);
}
let feltReview={mode:'monthly',index:0,playing:false,timer:null};
const feltText=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
function feltScene(scene){const title=feltText(scene.title);if(scene.type==='metric')return `<article class="felt-scene felt-review"><p class="felt-eyebrow">真实发生并被保留下来</p><h2 class="felt-title">${title}</h2><div class="felt-metric"><strong>${feltText(scene.value)}</strong><span>${feltText(scene.caption)}</span></div></article>`;if(scene.type==='keywords')return `<article class="felt-scene felt-review"><p class="felt-eyebrow">从事实中慢慢看见</p><h2 class="felt-title">${title}</h2><div class="felt-keywords">${scene.items.map(x=>`<span>${feltText(x)}</span>`).join('')}</div></article>`;if(scene.type==='fragments')return `<article class="felt-scene felt-review"><p class="felt-eyebrow">从事实中慢慢看见</p><h2 class="felt-title">${title}</h2><div class="felt-fragments">${scene.items.map(x=>`<div class="felt-fragment"><strong>${feltText(x[0])}</strong><p>${feltText(x[1])}</p></div>`).join('')}</div></article>`;if(scene.type==='quote')return `<article class="felt-scene felt-review"><p class="felt-eyebrow">${feltText(scene.eyebrow)}</p><div class="felt-quote"><blockquote>${feltText(scene.text)}</blockquote><p>${feltText(scene.caption)}</p></div></article>`;return `<article class="felt-scene felt-review"><p class="felt-eyebrow">${feltText(scene.eyebrow||'月度回望')}</p><h2 class="felt-title">${title}</h2><p class="felt-subtitle">${feltText(scene.subtitle)}</p></article>`}
function feltReviewScenes(mode){const r=state.monthlyReport;const cards=reportItems();const ability=abilityItems();if(mode==='yearly')return[
 {type:'metric',title:'这一年，你留下了自己的痕迹',value:String(cards.length||18),caption:'次由你确认并愿意保留的创造'},
 {type:'keywords',title:'它们组成了你的生活纹理',items:(ability.map(x=>x.label).slice(0,4).length?ability.map(x=>x.label).slice(0,4):['手作','边界','时间','同路人'])},
 {type:'fragments',title:'每一种能力，都有真实依据',items:(ability.slice(0,3).map(x=>[x.label,x.evidence||'来自你确认并保留的真实记录']).length?ability.slice(0,3).map(x=>[x.label,x.evidence||'来自你确认并保留的真实记录']):[['手工','完成两件旧衣修改并保留过程'],['组织','独立安排三次家庭活动'],['记录','为五件手工作品完成拍摄']])},
 {type:'fragments',title:'有些留下，有些被允许放下',items:[['持续','手作、旧物改造和作品记录'],['出现','小范围分享与线下活动'],['放下','暂时不公开经营自媒体账号']]},
 {type:'fragments',title:'碰在一起，先从很小的事开始',items:[['尝试','与伙伴完成一次作品记录'],['调整','从公开运营改为小范围分享'],['保留','继续寻找合适的同路人']]},
 {type:'fragments',title:'停下来，也属于这一年的轨迹',items:[['暂停','把更多时间留给家庭照护'],['回来','重新做了一件小作品'],['确认','节奏可以由自己决定']]},
 {type:'keywords',title:'这一年反复出现的词',items:['观察','整理','照护','创造']},
 {type:'quote',eyebrow:'写给下一年',text:'不需要一下子走得很远。',caption:'那些看起来很小的行动，也会留下属于自己的痕迹。'}
 ];const keywords=(r?.keywords||ability.map(x=>x.label)).slice(0,4);return[
 {type:'cover',eyebrow:'月度回望',title:r?.title||'这个月，你更认识自己了一点',subtitle:r?.summary||'这些内容来自你确认并愿意保留的记录。'},
 {type:'metric',title:'这个月，有一些事情被你留下',value:String(cards.length||5),caption:'件真实发生并由你确认的记录'},
 {type:'keywords',title:'它们慢慢有了名字',items:keywords.length?keywords:['手作','属于自己的时间','重新安排','被看见']},
 {type:'fragments',title:'你已经用过的能力',items:ability.length?ability.slice(0,3).map(x=>[x.label,x.evidence||'来自真实对话的能力证据']):[['协调力','在不同需要之间找到可行的安排'],['观察力','看见细节，并根据实际情况调整'],['持续照护','让日常生活保持运转']]},
 {type:'fragments',title:'有些停顿，也有真实原因',items:[['时间','完整的个人时间暂时变少'],['空间','仍在寻找合适的工作位置'],['选择','可以继续，也可以先停一停']]},
 {type:'quote',eyebrow:'写给下个月',text:'我想先看看，这件事能不能慢慢成为我的一部分。',caption:'不需要立刻决定，也不必一下子走得很远。'}
 ]}
function feltReviewPoster(){const scenes=feltReviewScenes(feltReview.mode);feltReview.index=Math.min(feltReview.index,scenes.length-1);const current=scenes[feltReview.index];return `<div class="felt-poster" data-felt-poster><img src="./src/felt/${feltReview.mode}.png" alt="${feltReview.mode==='monthly'?'月度':'年度'}毛毡回顾背景"/>${feltScene(current)}${feltReview.index===0&&!feltReview.playing?`<button class="felt-play" data-felt-action="play" aria-label="播放回顾">▶</button>`:''}<div class="felt-folio"><span>${feltReview.mode==='monthly'?'月度回望':'年度档案'}</span><span>${String(feltReview.index+1).padStart(2,'0')} / ${String(scenes.length).padStart(2,'0')}</span></div></div><div class="felt-controls"><button data-felt-action="previous" aria-label="上一幕">‹</button><div class="felt-progress"><i style="width:${(feltReview.index+1)/scenes.length*100}%"></i></div><button data-felt-action="next" aria-label="下一幕">›</button></div><p class="felt-save-note">轻点画面暂停或继续 · 长按约 600 毫秒可保存当前画面</p>`}
function fullReportPage(){const monthly=feltReview.mode==='monthly';const r=state.monthlyReport;const abilities=abilityItems().map(x=>x.label).slice(0,4);const cards=reportItems();const title=monthly?(r?.title||'这个月，你更认识自己了一点'):'这一年，你留下了自己的生活纹理';const summary=monthly?(r?.summary||'你在日常照护、整理和表达中，反复使用了观察与协调的能力。那些看起来很小的行动，正在慢慢形成属于你的方法。'):'这一年并不是一条笔直的路线。你有持续、有暂停，也有重新开始；每一次由你确认并愿意留下的记录，都让自己的方向更清楚了一点。';const monthlyKeywords=(r?.keywords?.length?r.keywords:(abilities.length?abilities:['观察','协调','整理','照护']));const keywords=monthly?monthlyKeywords:['手作','边界','时间','同路人'];return `<section class="felt-presentation-page active"><div class="felt-mode-switch"><button class="${monthly?'on':''}" data-felt-mode="monthly">月度回顾</button><button class="${monthly?'':'on'}" data-felt-mode="yearly">年度回顾</button></div><article class="felt-text-report ${monthly?'monthly-text-report':'yearly-text-report'}"><img src="./src/felt/${monthly?'monthly':'yearly'}.png" alt="${monthly?'月度':'年度'}毛毡文字报告背景"/><div class="felt-report-copy"><header><span>${monthly?'MONTHLY LETTER':'YEARLY LETTER'} · ${new Date().getFullYear()}</span><small>${monthly?`${new Date().getMonth()+1} 月回顾`:'年度回顾'}</small><h1>${feltText(title)}</h1><p>${feltText(summary)}</p></header><section class="felt-report-section"><small>这一段时间反复出现的词</small><div class="felt-report-keywords">${keywords.map(x=>`<b>${feltText(x)}</b>`).join('')}</div></section><section class="felt-report-section felt-report-evidence"><small>从真实记录中看见</small><p>${monthly?`这个月留下了 ${cards.length} 张由你确认的成长卡片。你不需要把它们变成成绩，它们只是帮助你看见自己已经做过什么。`:`这一年里，被留下的记录共同指向一种稳定的力量：你愿意观察真实情况，重新安排，并按照自己的节奏继续。`}</p></section><footer><span>由我确认并愿意保留</span><b>${monthly?'写给下个月的自己':'写给下一年的自己'}</b></footer></div></article><p class="felt-save-note">这是一页完整文字报告 · 长按可保存当前画面</p></section>`}
function cardDetailPage(index){const r=reportItems()[index];if(!r)return `<section class="detail-page card-detail active"><div class="real-data-empty"><h3>没有找到这张成长卡片</h3><p>它可能尚未生成，或已经从云端删除。</p></div></section>`;return `<section class="felt-presentation-page active"><div class="felt-poster felt-single"><img src="./src/felt/card.png" alt="单次成长卡片毛毡背景"/><article class="felt-scene"><time class="felt-card-date">我是誰 · 一次记录<b>${feltText(r.date)}</b></time><div class="felt-cloud-badge"><img src="./src/assets/cloud_ip/static/cloud_neutral.png" alt="云朵伙伴"/></div><div class="felt-single-copy"><p class="felt-eyebrow">今天被我重新看见的能力</p><h2 class="felt-title">${feltText(r.title)}</h2><p class="felt-subtitle">${feltText(r.summary||'这是从当前对话中由你确认并愿意留下的一段成长片段。')}</p></div><div class="felt-claim"><small>由我确认并愿意留下</small><p>这不是一句夸奖，而是今天真实发生过的一件事。</p><div class="felt-evidence"><strong>我的证据</strong><span>${feltText(r.conversationId?'来自关联对话中的真实记录':'来自你保存的成长记录')}</span></div></div></article><div class="felt-folio"><span>这一次</span><span>01 / 01</span></div></div><p class="felt-save-note">长按约 600 毫秒可保存当前画面</p></section>`}
function feltStop(){feltReview.playing=false;clearTimeout(feltReview.timer);feltReview.timer=null}
function feltSchedule(){clearTimeout(feltReview.timer);if(!feltReview.playing)return;feltReview.timer=setTimeout(()=>{const total=feltReviewScenes(feltReview.mode).length;if(feltReview.index>=total-1){feltStop()}else{feltReview.index++;render();feltSchedule()}},3000)}
document.addEventListener('click',event=>{const mode=event.target.closest('[data-felt-mode]');const action=event.target.closest('[data-felt-action]');const poster=event.target.closest('[data-felt-poster]');if(!mode&&!action&&!poster)return;event.preventDefault();event.stopImmediatePropagation();if(mode){feltStop();feltReview.mode=mode.dataset.feltMode;feltReview.index=0}else if(action){const total=feltReviewScenes(feltReview.mode).length;if(action.dataset.feltAction==='previous'){feltStop();feltReview.index=Math.max(0,feltReview.index-1)}if(action.dataset.feltAction==='next'){feltStop();feltReview.index=Math.min(total-1,feltReview.index+1)}if(action.dataset.feltAction==='play'){feltReview.index=0;feltReview.playing=true}}else{feltReview.playing=!feltReview.playing}render();feltSchedule()},true);

async function boot(){if(isLocalDevice&&localStorage.getItem('shiguang-device-login')==='active'){try{await hydrateAccount()}catch(error){console.warn('演示数据加载失败：',error.message)}state.loggedIn=true;state.profileSetup=false;render();return}const token=localStorage.getItem('shiguang-token');if(token){try{await apiRequest('/api/v1/auth/session');const profile=await hydrateAccount();state.loggedIn=true;state.profileSetup=!profile.onboardingComplete}catch{localStorage.removeItem('shiguang-token')}}render()}
boot();
